#!/bin/bash
# Name: XP Blue Theme
# Description: A classic look for Mike OS: blue taskbar, blue start menu and blue window title bars, a green start button and a blue-to-green hills wallpaper. Switch it on and off any time in the Themes app.
# Category: Themes
# Icon: preferences-desktop-theme
# Check: /usr/share/mikeos-amber/themes/xp-blue/theme.json
# Uninstall-Args: --uninstall
# Size: ~500 KB
#
# XP Blue theme for Mike OS: Amber (works on the full desktop and on Amber Lite).
# Also installs the Themes app if this computer doesn't have it yet.
set -u
USER_NAME=${SUDO_USER:-amber}; [ "$USER_NAME" = root ] && USER_NAME=amber
USER_HOME=$(getent passwd "$USER_NAME" | cut -d: -f6)

desktop_env() {   # the logged-in desktop's environment, so theme changes reach it
    local pid v val
    pid=$(pgrep -u "$USER_NAME" -x plasmashell | head -n 1)
    [ -z "$pid" ] && pid=$(pgrep -u "$USER_NAME" -x lxqt-panel | head -n 1)
    [ -z "$pid" ] && return 1
    for v in DISPLAY XAUTHORITY DBUS_SESSION_BUS_ADDRESS XDG_RUNTIME_DIR XDG_CURRENT_DESKTOP XDG_CONFIG_HOME; do
        val=$(tr '\0' '\n' < "/proc/$pid/environ" | grep "^$v=" | head -n 1)
        [ -n "$val" ] && printf '%s\n' "$val"
    done
}

if [ "${1:-}" = "--uninstall" ]; then
    # if XP Blue is in use, put Amber back first
    if [ "$(cat "$USER_HOME/.config/mikeos-amber/theme" 2>/dev/null)" = xp-blue ]; then
        echo "STATUS:Switching back to the Amber theme..."
        mapfile -t envs < <(desktop_env)
        sudo -u "$USER_NAME" env HOME="$USER_HOME" "${envs[@]}" python3 /usr/share/mikeos-amber/apps/themes.py --apply amber \
            >/dev/null 2>&1 < /dev/null || true
    fi
    rm -rf /usr/share/mikeos-amber/themes/xp-blue /usr/share/lxqt/themes/xp-blue /usr/share/themes/XP-Blue \
           /usr/share/color-schemes/XPBlue.colors /usr/share/wallpapers/MikeOS-XP-Blue /usr/share/plasma/desktoptheme/mikeos-xp-blue
    echo "XP Blue theme removed."
    exit 0
fi

echo "STATUS:Installing the XP Blue theme..."
T=$(mktemp -d)
mkdir -p "$T/theme" "$T/app"
base64 -d <<'XP_THEME_PAYLOAD' | tar -xzf - -C "$T/theme" || { echo "ERROR: the theme file is damaged - try again."; exit 1; }
